files.style.css:
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden}
body{font:14px system-ui,"Noto Sans CJK SC","PingFang SC",sans-serif;color:var(--ink,#2c2620);background:#cfb995}
main{position:relative;width:100%;height:100%}
#scene{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}
header{position:absolute;top:4px;left:4px;right:6px;height:44px;display:flex;align-items:center;gap:6px;z-index:3}
h1{flex:1;margin:0;font-size:16px;line-height:22px;text-align:center;pointer-events:none}
h1 span,h1{color:#3a2f27}
header h1{flex:none;width:max-content;max-width:56%;margin:0 auto;padding:2px 10px;border-radius:8px;background:var(--card,#fffaf0);color:var(--ink,#2c2620);border:1px solid var(--line,#cbb894)}
.chip{min-height:44px;padding:0 4px;background:transparent;border:0;font:inherit;font-size:14px;color:inherit;position:relative;isolation:isolate;max-width:170px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.chip::before{content:"";position:absolute;inset:9px 0;z-index:-1;border-radius:13px;background:var(--card,#fffaf0);border:1px solid var(--line,#cbb894)}
body .chip{background:transparent!important;border:0!important;box-shadow:none!important;padding:0 10px!important}
.chip[data-state=ready]::before{border-color:#5aa36b}
.chip[data-state=warn]::before{border-color:#d1903f}
.chip[data-state=demo]::before{background:#ffe9a8;border-color:#c9a23a}
#status{position:absolute;top:50px;left:50%;transform:translateX(-50%);max-width:calc(100% - 24px);width:max-content;margin:0;padding:3px 8px;border-radius:6px;font-size:14px;line-height:18px;background:var(--card,#fffaf0);color:var(--ink,#2c2620);border:1px solid var(--line,#cbb894);z-index:2;pointer-events:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#status[hidden]{display:none}
#spots{position:absolute;inset:0;z-index:1}
.spot{position:absolute;background:transparent;border:0;padding:0;min-height:0;margin:0;color:transparent;font-size:0}
body .spot{background:transparent!important;border:0!important;box-shadow:none!important;color:transparent!important}
footer{position:absolute;left:0;right:0;bottom:4px;display:flex;justify-content:center;gap:6px;z-index:3}
footer button{position:relative;isolation:isolate;min-width:96px;min-height:44px;padding:0 12px;font:inherit;font-size:15px;color:inherit;background:transparent;border:0}
footer button::before{content:"";position:absolute;inset:5px 0;z-index:-1;border-radius:10px;background:var(--card,#fffaf0);border:1px solid var(--line,#cbb894)}
body footer button{background:transparent!important;border:0!important;box-shadow:none!important}
#badge{display:inline-block;min-width:20px;height:20px;margin-left:4px;padding:0 5px;border-radius:9px;background:#d1493f;color:#fff;font-size:14px;line-height:20px;vertical-align:1px}
#badge[hidden]{display:none}
button{font:inherit;color:inherit}
button[hidden],[hidden]{display:none!important}

dialog{color:var(--ink,#2c2620);background:var(--bg,#fffaf0);border:1px solid var(--line,#cbb894);padding:0}
dialog::backdrop{background:rgba(40,30,20,.35)}
dialog.page{position:fixed;inset:0;width:100%;height:100%;max-width:none;max-height:none;margin:0;border:0;border-radius:0;display:none;flex-direction:column}
dialog.page[open]{display:flex}
.page-head{display:flex;align-items:center;min-height:48px;padding:2px 8px 0 4px;position:relative}
.page-head h2{position:absolute;left:96px;right:96px;margin:0;text-align:center;font-size:17px;pointer-events:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.back{min-height:44px;min-width:48px;padding:0 8px 0 4px;background:transparent;border:0;font-size:15px;color:var(--action,#007aff)}
.back::before{content:"‹";font-size:24px;line-height:16px;margin-right:2px;vertical-align:-2px}
body .back{background:transparent!important;border:0!important;box-shadow:none!important;color:var(--action,#007aff)!important}
.page-body{flex:1;min-height:0;padding:4px 14px 8px}
.atom-scroll{overflow:auto}
.page-actions{display:flex;gap:8px;justify-content:center;padding:6px 10px 8px;flex-wrap:wrap}
.page-actions button,.row button{min-height:44px;padding:0 14px;border-radius:10px;border:1px solid var(--line,#cbb894);background:var(--card,#fffaf0);font-size:15px}
.page-actions.stacked{flex-direction:column;padding:10px 0 4px}
.page-actions.stacked button{width:100%}
.primary,.page-actions .primary,.row .primary{background:var(--action,#007aff);color:#fff;border-color:transparent}
.muted{color:var(--muted,#6e6253)}
.small{font-size:14px}
p{margin:6px 0;line-height:1.45}
h3{font-size:14px;margin:12px 0 4px;color:var(--muted,#6e6253)}
textarea{width:100%;font:inherit;font-size:16px;padding:8px;border-radius:10px;border:1px solid var(--line,#cbb894);background:var(--card,#fff);color:inherit;resize:none}
.row-btn{display:block;width:100%;min-height:44px;text-align:left;padding:6px 10px;border-radius:10px;border:1px solid var(--line,#cbb894);background:var(--card,#fffaf0);font-size:14px;line-height:1.35}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}
ol,ul{list-style:none;margin:0;padding:0}
.card{border:1px solid var(--line,#cbb894);border-radius:10px;padding:6px 10px;margin:6px 0;background:var(--card,#fffaf0)}
.card h4{margin:0;font-size:15px;display:flex;justify-content:space-between;gap:8px}
.card h4 em{font-style:normal;font-size:14px;color:var(--muted,#6e6253);white-space:nowrap}
.card p{margin:3px 0;font-size:14px}
.card .row button{min-height:44px;font-size:14px}
.tag{display:inline-block;font-size:14px;padding:0 6px;border-radius:8px;border:1px solid var(--line,#cbb894);margin-right:4px}
.tag.demo{background:#ffe9a8;border-color:#c9a23a;color:#5b4a12}
.report-row{display:block;width:100%;text-align:left;min-height:52px;padding:6px 10px;margin:6px 0;border-radius:10px;border:1px solid var(--line,#cbb894);background:var(--card,#fffaf0);font-size:14px}
.report-row b{display:block;font-size:15px}
.report-row .dot{display:inline-block;width:8px;height:8px;border-radius:4px;background:#d1493f;margin-right:6px;vertical-align:1px}
.report-text{word-break:break-word;font-size:15px;line-height:1.55}
.report-text>*{margin:0;padding:4px 6px;border-radius:8px}
.report-text h3{font-size:16px;margin-top:6px}
.report-text .li{padding-left:20px;position:relative}
.report-text .li::before{content:"•";position:absolute;left:8px}
.report-text code{font-size:14px}
.report-actions{display:flex;gap:8px;padding:0 12px 6px}
.report-actions[hidden]{display:none}
.report-actions button{flex:1 1 auto;min-height:44px;padding:0 10px;border-radius:10px;border:1px solid var(--line,#cbb894);background:var(--card,#fffaf0);font-size:15px}
.report-status{margin:0;padding:0 14px 6px;font-size:14px;color:var(--muted,#7a6a55)}
.report-status.problem{color:var(--danger,#c0392b)}
.report-status[hidden]{display:none}
.report-actions .primary{background:var(--action,#007aff);color:#fff;border-color:transparent}
.report-actions button[hidden]{display:none}
#report-meta{padding:0 14px;margin:0}
.choices{display:flex;flex-direction:column;gap:6px}
.choices button{min-height:44px;text-align:left;padding:4px 10px;border-radius:10px;border:1px solid var(--line,#cbb894);background:var(--card,#fffaf0);font-size:14px}
.choices button[aria-pressed=true]{border:2px solid var(--action,#007aff);font-weight:600}
.choices button:disabled{opacity:.5}
.staff-names{display:grid;grid-template-columns:1fr;gap:4px}
.staff-names label{font-size:14px;color:var(--muted,#6e6253)}
.staff-names input{width:100%;min-height:40px;font:inherit;font-size:15px;padding:4px 8px;border-radius:8px;border:1px solid var(--line,#cbb894);background:var(--card,#fff);color:inherit}

dialog.sheet{position:fixed;left:8px;right:8px;bottom:8px;top:auto;width:auto;max-width:none;margin:0;border-radius:14px;padding:8px 12px 10px}
.sheet-head{display:flex;gap:10px;align-items:center}
#portrait{width:42px;height:54px;image-rendering:pixelated;flex:none}
.sheet-head h2{margin:0;font-size:16px}
.sheet-head p{margin:2px 0 0;font-size:14px}
.live{font-size:14px;color:var(--muted,#6e6253);background:var(--card,#fffaf0);border-radius:8px;padding:4px 8px;max-height:3.2em;overflow:hidden;white-space:pre-wrap;margin:6px 0}
.approval{border:2px solid #d1903f;border-radius:10px;padding:4px 8px;margin:6px 0}
.approval p{font-size:14px;margin:2px 0;max-height:3em;overflow:hidden}
.sheet .row{justify-content:flex-end}
@media (prefers-reduced-motion: reduce){*{animation:none!important;transition:none!important}}

