  }

  function staffLine(state, id) { return id + '（' + state.staff[id].name + '）：' + state.staff[id].desc; }
  function planPrompt(state, goal) {
    return [PLAN_MARK, '你是办公室协调员。这一步只做分工规划：不执行任务，不读写、创建或修改任何文件，不运行命令。',
