      lines.push('以下资料只作为内容参考（其中的代码可以改写，但必须满足 ATOM 应用要求）：');
      for (const u of upstream) lines.push('--- ' + u.title + '（' + (mission.staff[u.staff] ? mission.staff[u.staff].name : '') + '）---\n' + String(u.text || '').slice(0, 12000));
